entries[21215] = { ["name"] = "Graccus hausgemachte Früchtepastete", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Stufe 40\nBenutzen: Stellt 20 Sek. lang jede Sekunde 5% Eurer Gesundheit und Eures Manas wieder her. Ihr müsst beim Essen sitzen bleiben. Lasst Euch den leckeren Stollen schmecken.\n\"Mit Graccus Spezialgewürzen haltbar gemacht! Es wird eine ganze Weile dauern, bis das hier schlecht wird...\"" }
